 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Use repeated local texture to reconstruct cells hidden by the 6 mask.
    # For each masked location find the best matching translated neighborhood.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            best_score = -1
            best_val = 0
            for sr in range(h):
                for sc in range(w):
                    if grid[sr][sc] == 6:
                        continue
                    score = 0
                    compared = 0
                    for dr in range(-5, 6):
                        for dc in range(-5, 6):
                            tr, tc, ar, ac = r+dr, c+dc, sr+dr, sc+dc
                            if (0 <= tr < h and 0 <= tc < w and
