                                grid[tr][tc] != 6 and grid[ar][ac] != 6):
                                compared += 1
                                if grid[tr][tc] == grid[ar][ac]:
                                    score += 1
                    # Prefer substantial exact matches; normalize for border/mask overlap.
                    if compared and score * 1000 // compared > best_score:
                        best_score = score * 1000 // compared
                        best_val = grid[sr][sc]
            out[r][c] = best_val
    return out
